if(id==='dns'){
 const p=make(id,'<div class="a-columns">'+panel('Tra cứu DNS',field('ut-dns-name','Tên miền','example.com')+'<label for="ut-dns-type">Loại bản ghi</label><select id="ut-dns-type">'+['A','AAAA','MX','TXT','CNAME','NS','SOA','CAA'].map(t=>'<option>'+t+'</option>').join('')+'</select><div class="a-toolbar"><button class="a-primary u-run">Tra cứu DNS</button></div><p class="a-hint">Truy vấn trực tuyến tới Google Public DNS qua HTTPS. Tên miền và loại bản ghi được gửi tới dns.google; nhà cung cấp nhận thông tin kết nối của bạn. Kết quả là góc nhìn của resolver, có thể khác DNS nội bộ hoặc máy của bạn.</p>')+panel('Kết quả DNS','<div class="u-dns-records"></div>'+ta('ut-dns-output','Phản hồi DNS')+outputButtons)+'</div>');let result='',revision=0;q(p,'#ut-dns-output').readOnly=true;const clear=()=>{revision++;p.cancel?.();result='';q(p,'#ut-dns-output').value='';q(p,'.u-dns-records').replaceChildren();ready(p,false);status(p,'')};q(p,'.u-run').onclick=async()=>{clear();const current=revision;let timer;try{const name=C.dnsDomain(q(p,'#ut-dns-name').value),type=q(p,'#ut-dns-type').value,ctrl=new AbortController();p.cancel=()=>{revision++;ctrl.abort();clearTimeout(timer);q(p,'.u-run').disabled=false;p.cancel=null;return true};q(p,'.u-run').disabled=true;timer=setTimeout(()=>ctrl.abort(),12000);status(p,'Đang tra cứu DNS…');const res=await fetch('https://dns.google/resolve?name='+encodeURIComponent(name)+'&type='+type,{signal:ctrl.signal,credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store'});if(!res.ok)throw Error('Dịch vụ DNS trả lỗi HTTP '+res.status);const data=await res.json();if(current!==revision)return;if(!Number.isInteger(data.Status))throw Error('Phản hồi DNS chưa hợp lệ.');result=JSON.stringify({resolver:'Google Public DNS',name,type,...data},null,2);q(p,'#ut-dns-output').value=result;for(const r of data.Answer||[]){const row=document.createElement('p');row.textContent=r.name+' · type '+r.type+' · TTL '+r.TTL+' · '+r.data;q(p,'.u-dns-records').append(row)}ready(p,true);status(p,data.Status===0?((data.Answer||[]).length?'Đã nhận bản ghi DNS.':'Không có bản ghi loại này trong câu trả lời.'):data.Status===3?'NXDOMAIN: tên miền không tồn tại theo resolver.':'DNS trả trạng thái '+data.Status,data.Status!==0)}catch(e){if(current!==revision)return;if(e.name==='AbortError')status(p,'Tra cứu đã dừng hoặc quá thời gian chờ.',true);else status(p,e.message,true)}finally{clearTimeout(timer);if(current===revision){p.cancel=null;q(p,'.u-run').disabled=false}}};p.querySelectorAll('input,select').forEach(el=>el.oninput=clear);outputActions(p,()=>result,'toolhub-dns.json','application/json');return p;
}
